from dataclasses import dataclass
import hashlib
import hmac
import string


_ITERATIONS = 20000
_ALLOWED_HANDLE = frozenset(string.ascii_letters + string.digits + "_")


def _normalize_address(address):
    if not isinstance(address, str):
        raise TypeError("address must be a string")
    normalized = address.strip().lower()
    if normalized.count("@") != 1:
        raise ValueError("invalid address")
    local, domain = normalized.split("@")
    if not local or not domain or "." not in domain:
        raise ValueError("invalid address")
    return normalized


@dataclass(frozen=True)
class CredentialRecord:
    handle: str
    address: str
    encoded_secret: str

    def verify_secret(self, candidate):
        if not isinstance(candidate, str):
            return False
        try:
            marker, count_text, salt_hex, digest_hex = self.encoded_secret.split("$")
            if marker != "pbkdf2" or count_text != str(_ITERATIONS):
                return False
            salt = bytes.fromhex(salt_hex)
            expected = bytes.fromhex(digest_hex)
            if not 1 <= len(salt) <= 32 or len(expected) != 32:
                return False
            if salt.hex() != salt_hex or expected.hex() != digest_hex:
                return False
        except (AttributeError, TypeError, ValueError):
            return False
        actual = hashlib.pbkdf2_hmac(
            "sha256", candidate.encode("ascii"), salt, _ITERATIONS
        )
        return hmac.compare_digest(actual, expected)


def create_credential(handle, address, secret, salt):
    if not isinstance(handle, str):
        raise TypeError("handle must be a string")
    effective_length = sum(char != "_" for char in handle)
    if not handle or effective_length > 20 or any(char not in _ALLOWED_HANDLE for char in handle):
        raise ValueError("invalid handle")
    normalized = _normalize_address(address)
    if not isinstance(secret, str):
        raise TypeError("secret must be a string")
    if not secret:
        raise ValueError("secret must not be empty")
    try:
        salt_bytes = bytes(memoryview(salt))
    except (TypeError, ValueError) as exc:
        raise TypeError("salt must be bytes-like") from exc
    if not 1 <= len(salt_bytes) <= 32:
        raise ValueError("salt must contain 1 through 32 bytes")
    digest = hashlib.pbkdf2_hmac(
        "sha256", secret.encode("utf-8"), salt_bytes, _ITERATIONS
    )
    encoded = "pbkdf2${}${}${}".format(
        _ITERATIONS, salt_bytes.hex(), digest.hex()
    )
    return CredentialRecord(handle, normalized, encoded)

